from work import *
id='local049'
base='''WITH dates AS (SELECT DISTINCT company_id,date_joined,year_founded FROM companies_dates), industries AS (SELECT DISTINCT company_id,industry FROM companies_industries), new_companies AS (SELECT d.company_id,CAST(strftime('%Y',d.date_joined) AS INTEGER) year,i.industry FROM dates d JOIN industries i USING(company_id) WHERE d.date_joined>='2019-01-01' AND d.date_joined<'2022-01-01'), totals AS (SELECT industry,count(distinct company_id) total FROM new_companies GROUP BY industry) '''
query(id,base+'SELECT industry,total,total/3.0 average_new_companies FROM totals ORDER BY total DESC LIMIT 10','top-industries.json')
query(id,base+'SELECT year,industry,count(distinct company_id) n FROM new_companies GROUP BY 1,2 ORDER BY year,n DESC','year-industry-counts.json',100)
query(id,base+"SELECT industry,count(distinct d.company_id) founded_total FROM dates d JOIN industries i USING(company_id) WHERE year_founded BETWEEN 2019 AND 2021 GROUP BY industry ORDER BY founded_total DESC LIMIT 5",'founded-alternative.json')
query(id,"SELECT count(*) rows,count(distinct d.company_id) companies FROM companies_dates d JOIN companies_industries i USING(company_id) WHERE date_joined>='2019-01-01' AND date_joined<'2022-01-01'",'raw-join-multiplicity.json')
fields={'population.eligibility':{'value':'Companies with joined date in interval and known industry; distinct company IDs','basis':'assumed','rationale':'new unicorn is date joined not founding; distinct IDs count company entities'},'population.conditions':{'value':["company joining unicorn list 2019..2021"],'basis':'request','quote':'new unicorn companies'},'population.time':{'value':'2019-01-01 inclusive to 2022-01-01 exclusive, 3 calendar years','basis':'request','quote':'from 2019 to 2021'},'measure.formula':{'value':{'op':'custom','description':'Distinct new company IDs by industry across 3 years; choose highest total industry; average yearly new company count=total/3.0, including zero years'},'basis':'assumed','rationale':'top industry over entire requested period; yearly average has 3-year denominator'},'grouping':{'value':['industry'],'basis':'request','quote':'top industry'},'selection':{'value':{'n':1,'orderBy':'total DESC, industry ASC'},'basis':'request','quote':'top industry'},'selection.ties':'strict','output':{'value':{'rowMode':'top_n','rowCount':1,'columns':['industry','average_new_companies']},'basis':'request','quote':'average number of new unicorn companies per year'}}
finish(id,fields,base+'SELECT industry,total/3.0 average_new_companies FROM totals ORDER BY total DESC,industry LIMIT 1',{'algorithm':'date_joined years, distinct company ID, fixed top industry by 3-year additions, total/3','assumptions':['date_joined is unicorn entry','top by additions not valuation','fixed industry not yearly changing']});progress(id,'frozen');reveal(id)
